/* Custom NickxSlider Engine for WooCommerce Product Video Gallery Slider */
(function (nquery) {
    function NickxSlider(container, options) {
        this.options = options || {};
        this.$container = nquery(container);
        if (!this.$container.length) return;
        this.container = this.$container.get(0);
        this.$wrapper = this.$container.children('.nswiper-wrapper');
        if (!this.$wrapper.length) {
            this.$wrapper = this.$container.find('.nswiper-wrapper');
        }

        this.direction = this.options.direction || 'horizontal';
        this.effect = this.options.effect || 'slide';
        this.loop = !!this.options.loop;
        this.rtl = !!this.options.rtl || this.$container.attr('dir') === 'rtl' || nquery('body').hasClass('rtl') || nquery('html').attr('dir') === 'rtl';
        this.autoHeight = !!this.options.autoHeight;
        this.slideActiveClass = this.options.slideActiveClass || 'nswiper-slide-active';
        this.thumbs = this.options.thumbs ? this.options.thumbs.nswiper : null;
        this.slidesPerView = parseInt(this.options.slidesPerView, 10) || 1;
        this.spaceBetween = parseInt(this.options.spaceBetween, 10) || 0;

        this.activeIndex = 0;
        this.realIndex = 0;
        this.autoplayTimer = null;
        this.isAutoplayRunning = false;

        var self = this;
        this.autoplay = {
            start: function () { self.startAutoplay(); },
            stop: function () { self.stopAutoplay(); }
        };

        this.init();
    }

    NickxSlider.prototype.init = function () {
        var self = this;
        this.updateSlides();

        if (this.options.navigation) {
            var nextBtn = this.options.navigation.nextEl;
            var prevBtn = this.options.navigation.prevEl;
            if (this.options.navigation.enabled) {
                this.$container.removeClass('nswiper-navigation-disabled');
                if (nextBtn) {
                    nquery(nextBtn).show().off('click.nickxSlider').on('click.nickxSlider', function (e) {
                        e.preventDefault();
                        self.slideNext();
                    });
                }
                if (prevBtn) {
                    nquery(prevBtn).show().off('click.nickxSlider').on('click.nickxSlider', function (e) {
                        e.preventDefault();
                        self.slidePrev();
                    });
                }
            } else {
                this.$container.addClass('nswiper-navigation-disabled');
                if (nextBtn) nquery(nextBtn).hide();
                if (prevBtn) nquery(prevBtn).hide();
            }
        }

        if (this.options.autoplay && this.options.autoplay.enabled && this.options.autoplay.pauseOnMouseEnter) {
            this.$container.off('mouseenter.nickxSlider mouseleave.nickxSlider')
                .on('mouseenter.nickxSlider', function () {
                    self.pauseAutoplay();
                })
                .on('mouseleave.nickxSlider', function () {
                    self.resumeAutoplay();
                });
        }

        this.initSwipe();

        if (this.thumbs && this.thumbs.$container) {
            this.thumbs.$container.off('click.nickxThumbs', '.nswiper-slide').on('click.nickxThumbs', '.nswiper-slide', function (e) {
                var clickedIndex = self.thumbs.$slides.index(this);
                if (clickedIndex !== -1) {
                    self.goToSlide(clickedIndex, true);
                }
            });
        }

        if (this.options.autoplay && this.options.autoplay.enabled) {
            this.startAutoplay();
        }

        nquery(window).on('resize.nickxSlider', function () {
            self.update();
        });

        if (this.options.on && typeof this.options.on.init === 'function') {
            this.options.on.init(this);
        }

        this.$container.find('video, img').off('loadedmetadata.nickxAutoHeight load.nickxAutoHeight').on('loadedmetadata.nickxAutoHeight load.nickxAutoHeight', function () {
            if (self.autoHeight) {
                self.updateAutoHeight();
            }
        });

        this.goToSlide(0, false);
    };

    NickxSlider.prototype.updateSlides = function () {
        this.$slides = this.$wrapper.children('.nswiper-slide');
        this.slidesCount = this.$slides.length;

        this.$slides.each(function (index) {
            nquery(this).attr('data-nswiper-slide-index', index);
        });

        this.applyLayoutStyles();
    };

    NickxSlider.prototype.applyLayoutStyles = function () {
        this.$container.css({ 'position': 'relative', 'overflow': 'hidden' });
        if (this.rtl) {
            this.$container.addClass('nswiper-rtl');
        } else {
            this.$container.removeClass('nswiper-rtl');
        }
        if (this.direction === 'vertical') {
            this.$container.addClass('nswiper-vertical').removeClass('nswiper-horizontal');
        } else {
            this.$container.addClass('nswiper-horizontal').removeClass('nswiper-vertical');
        }
        if (this.autoHeight) {
            this.$container.addClass('nswiper-autoheight');
        } else {
            this.$container.removeClass('nswiper-autoheight');
        }

        if (this.effect === 'fade') {
            this.$wrapper.css({ 'position': 'relative', 'display': 'block', 'width': '100%' });
            this.$slides.css({
                'position': 'absolute',
                'top': '0',
                'left': '0',
                'width': '100%',
                'opacity': '0',
                'transition': 'opacity 0.3s ease',
                'z-index': '1',
                'pointer-events': 'none'
            });
            this.$slides.eq(this.activeIndex).css({
                'opacity': '1',
                'z-index': '2',
                'pointer-events': 'auto'
            });
        } else {
            if (this.direction === 'horizontal') {
                this.$wrapper.css({
                    'display': 'flex',
                    'flex-direction': 'row',
                    'transition': 'transform 0.3s ease',
                    'width': '100%'
                });
                var containerWidth = this.$container.width() || 500;
                var slideWidth = (containerWidth - (this.slidesPerView - 1) * this.spaceBetween) / this.slidesPerView;
                if (this.rtl) {
                    this.$slides.css({
                        'flex-shrink': '0',
                        'width': slideWidth + 'px',
                        'margin-left': this.spaceBetween + 'px',
                        'margin-right': '0px'
                    });
                } else {
                    this.$slides.css({
                        'flex-shrink': '0',
                        'width': slideWidth + 'px',
                        'margin-right': this.spaceBetween + 'px',
                        'margin-left': '0px'
                    });
                }
            } else {
                this.$wrapper.css({
                    'display': 'flex',
                    'flex-direction': 'column',
                    'transition': 'transform 0.3s ease'
                });
                var containerHeight = this.$container.height() || 400;
                var slideHeight = (containerHeight - (this.slidesPerView - 1) * this.spaceBetween) / this.slidesPerView;
                this.$slides.css({
                    'flex-shrink': '0',
                    'height': slideHeight + 'px',
                    'margin-bottom': this.spaceBetween + 'px'
                });
            }
        }
    };

    NickxSlider.prototype.goToSlide = function (index, animate) {
        if (this.slidesCount === 0) return;

        if (index < 0) {
            index = this.loop ? this.slidesCount - 1 : 0;
        } else if (index >= this.slidesCount) {
            index = this.loop ? 0 : this.slidesCount - 1;
        }

        if (document.activeElement && document.activeElement !== document.body) {
            if (typeof document.activeElement.blur === 'function') {
                try { document.activeElement.blur(); } catch (err) { }
            }
        }

        if (this.options.on && typeof this.options.on.slideChangeTransitionStart === 'function') {
            this.options.on.slideChangeTransitionStart(this);
        }

        this.activeIndex = index;
        this.realIndex = index;

        this.$slides.removeClass(this.slideActiveClass).removeAttr('aria-hidden');
        var $activeSlide = this.$slides.eq(index);
        $activeSlide.addClass(this.slideActiveClass);

        if (this.effect === 'fade') {
            this.$slides.css({ 'opacity': '0', 'z-index': '1', 'pointer-events': 'none' });
            $activeSlide.css({ 'opacity': '1', 'z-index': '2', 'pointer-events': 'auto' });
        } else {
            var maxIndex = Math.max(0, this.slidesCount - this.slidesPerView);
            var targetIndex = Math.max(0, Math.min(index, maxIndex));
            if (this.direction === 'horizontal') {
                var containerWidth = this.$container.width() || 500;
                var slideWidth = (containerWidth - (this.slidesPerView - 1) * this.spaceBetween) / this.slidesPerView;
                var offset = targetIndex * (slideWidth + this.spaceBetween);
                if (!this.rtl) {
                    offset = -offset;
                }
                this.$wrapper.css({
                    'transform': 'translate3d(' + offset + 'px, 0px, 0px)',
                    'transition': animate !== false ? (this.autoHeight ? 'transform 0.3s ease, height 0.3s ease' : 'transform 0.3s ease') : 'none'
                });
            } else {
                var containerHeight = this.$container.height() || 400;
                var slideHeight = (containerHeight - (this.slidesPerView - 1) * this.spaceBetween) / this.slidesPerView;
                var vOffset = -(targetIndex * (slideHeight + this.spaceBetween));
                this.$wrapper.css({
                    'transform': 'translate3d(0px, ' + vOffset + 'px, 0px)',
                    'transition': animate !== false ? (this.autoHeight ? 'transform 0.3s ease, height 0.3s ease' : 'transform 0.3s ease') : 'none'
                });
            }
        }

        if (this.autoHeight) {
            this.updateAutoHeight();
        }

        this.updateNavigation();

        if (this.thumbs && typeof this.thumbs.goToSlide === 'function') {
            this.thumbs.goToSlide(index, true);
            this.thumbs.$slides.removeClass('nswiper-slide-thumb-active');
            this.thumbs.$slides.eq(index).addClass('nswiper-slide-thumb-active');
        }

        if (this.options.on && typeof this.options.on.slideChange === 'function') {
            this.options.on.slideChange(this);
        }
    };

    NickxSlider.prototype.updateNavigation = function () {
        if (!this.options.navigation || !this.options.navigation.enabled) return;

        var nextBtn = this.options.navigation.nextEl;
        var prevBtn = this.options.navigation.prevEl;
        if (!nextBtn && !prevBtn) return;

        var $next = nquery(nextBtn);
        var $prev = nquery(prevBtn);

        var maxIndex = Math.max(0, this.slidesCount - this.slidesPerView);

        if (!this.loop) {
            if (this.activeIndex <= 0) {
                $prev.addClass('nswiper-button-disabled').attr('aria-disabled', 'true');
            } else {
                $prev.removeClass('nswiper-button-disabled').removeAttr('aria-disabled');
            }

            if (this.activeIndex >= maxIndex) {
                $next.addClass('nswiper-button-disabled').attr('aria-disabled', 'true');
            } else {
                $next.removeClass('nswiper-button-disabled').removeAttr('aria-disabled');
            }
        } else {
            $prev.removeClass('nswiper-button-disabled').removeAttr('aria-disabled');
            $next.removeClass('nswiper-button-disabled').removeAttr('aria-disabled');
        }
    };

    NickxSlider.prototype.slideNext = function (userTriggered) {
        this.goToSlide(this.activeIndex + 1, true);
        if (userTriggered !== false) {
            this.resetAutoplay();
        }
    };

    NickxSlider.prototype.slidePrev = function () {
        this.goToSlide(this.activeIndex - 1, true);
        this.resetAutoplay();
    };

    NickxSlider.prototype.slideTo = function (index) {
        this.goToSlide(index, true);
        this.resetAutoplay();
    };

    NickxSlider.prototype.slideToLoop = function (index) {
        this.goToSlide(index, true);
        this.resetAutoplay();
    };

    NickxSlider.prototype.update = function () {
        this.updateSlides();
        this.goToSlide(this.activeIndex, false);
    };

    NickxSlider.prototype.updateAutoHeight = function () {
        if (!this.autoHeight) {
            this.$container.removeClass('nswiper-autoheight');
            this.$container.css('height', '');
            this.$wrapper.css('height', '');
            return;
        }

        this.$container.addClass('nswiper-autoheight');
        this.$container.css('height', '');

        var $activeSlide = this.$slides.eq(this.activeIndex);
        if (!$activeSlide.length || !$activeSlide[0]) return;

        var targetHeight = $activeSlide[0].offsetHeight || $activeSlide.outerHeight() || 0;

        if (targetHeight && targetHeight > 0) {
            this.$wrapper.css({
                'height': targetHeight + 'px'
            });
        }
    };

    NickxSlider.prototype.loopCreate = function () {
        this.update();
    };

    NickxSlider.prototype.loopDestroy = function () {
        this.update();
    };

    NickxSlider.prototype.startAutoplay = function () {
        var self = this;
        this.stopAutoplay();
        if (this.options.autoplay && this.options.autoplay.enabled && this.slidesCount > 1) {
            this.isAutoplayRunning = true;
            this.autoplayTimer = setInterval(function () {
                self.slideNext(false);
            }, 4000);
        }
    };

    NickxSlider.prototype.resetAutoplay = function () {
        if (this.isAutoplayRunning || (this.options.autoplay && this.options.autoplay.enabled && this.slidesCount > 1)) {
            this.startAutoplay();
        }
    };

    NickxSlider.prototype.stopAutoplay = function () {
        if (this.autoplayTimer) {
            clearInterval(this.autoplayTimer);
            this.autoplayTimer = null;
        }
        this.isAutoplayRunning = false;
    };

    NickxSlider.prototype.pauseAutoplay = function () {
        if (this.autoplayTimer) {
            clearInterval(this.autoplayTimer);
            this.autoplayTimer = null;
        }
    };

    NickxSlider.prototype.resumeAutoplay = function () {
        if (this.isAutoplayRunning && !this.autoplayTimer) {
            this.startAutoplay();
        }
    };

    NickxSlider.prototype.initSwipe = function () {
        var self = this;
        var startX = 0, startY = 0, distX = 0, distY = 0;
        var isDragging = false;

        function getPointerPos(e) {
            if (e.originalEvent && e.originalEvent.touches && e.originalEvent.touches.length) {
                return { x: e.originalEvent.touches[0].pageX, y: e.originalEvent.touches[0].pageY };
            }
            if (e.originalEvent && e.originalEvent.changedTouches && e.originalEvent.changedTouches.length) {
                return { x: e.originalEvent.changedTouches[0].pageX, y: e.originalEvent.changedTouches[0].pageY };
            }
            return { x: e.pageX, y: e.pageY };
        }

        this.$container.on('touchstart.nickxSlider mousedown.nickxSlider', function (e) {
            if (self.options.allowTouchMove === false || self.slidesCount <= self.slidesPerView) {
                return;
            }
            if (e.type === 'mousedown' && e.which !== 1) return;

            var pos = getPointerPos(e);
            startX = pos.x;
            startY = pos.y;
            distX = 0;
            distY = 0;
            isDragging = true;
        });

        nquery(document).on('mousemove.nickxSlider touchmove.nickxSlider', function (e) {
            if (!isDragging) return;
            var pos = getPointerPos(e);
            distX = pos.x - startX;
            distY = pos.y - startY;
        });

        nquery(document).on('mouseup.nickxSlider touchend.nickxSlider', function (e) {
            if (!isDragging) return;
            isDragging = false;

            var threshold = 35;

            if (self.direction === 'vertical') {
                if (Math.abs(distY) > threshold && Math.abs(distY) > Math.abs(distX)) {
                    if (distY < 0) {
                        self.slideNext();
                    } else {
                        self.slidePrev();
                    }
                }
            } else {
                if (Math.abs(distX) > threshold && Math.abs(distX) > Math.abs(distY)) {
                    if (self.rtl) {
                        if (distX < 0) {
                            self.slidePrev();
                        } else {
                            self.slideNext();
                        }
                    } else {
                        if (distX < 0) {
                            self.slideNext();
                        } else {
                            self.slidePrev();
                        }
                    }
                }
            }
        });
    };

    window.NickxSlider = NickxSlider;
    window.nSwiper = NickxSlider;
})(jQuery);